+use crate::graph::Graph;
+
+struct Workspace {
+    pending: Vec<usize>,
+    range: Vec<std::ops::Range<usize>>,
+    signature: Vec<(u8, usize)>,
+    incoming: Graph,
+    scheduled: Vec<bool>,
+    changed: Vec<(usize, usize)>,
+}
