+    order: Vec<usize>,
+    boundary: Vec<usize>,
+    workspace: Option<Workspace>,
+}
+
+impl Search {
+    pub fn new(edge: &Graph, mut color: Vec<usize>) -> Self {
+        let mut order = (0..color.len()).collect::<Vec<_>>();
+        order.sort_unstable_by_key(|&index| color[index]);
+        let mut boundary = vec![0; color.len()];
+        let mut pending = Vec::new();
+        let mut start = 0;
+        for end in 1..=order.len() {
+            if end < order.len() && color[order[end - 1]] == color[order[end]] {
+                continue;
+            }
+            boundary[start] = end;
+            if end - start > 1 {
+                pending.push(start);
+            }
+            start = end;
+        }
+        let mut start = 0;
+        while start < order.len() {
+            let end = boundary[start];
+            for &index in &order[start..end] {
+                color[index] = start;
+            }
+            start = end;
+        }
+        let workspace = (!pending.is_empty()).then(|| {
+            let mut length = 0;
+            let range = edge
+                .iter()
+                .map(|adjacent| {
+                    let start = length;
+                    length += adjacent.len();
+                    start..length
+                })
+                .collect();
+            Workspace {
+                pending,
+                range,
+                signature: vec![(0, 0); length],
+                incoming: Graph::new(
+                    color.len(),
+                    edge.iter().enumerate().flat_map(|(source, adjacent)| {
+                        adjacent
+                            .iter()
+                            .map(move |&(kind, target)| (target, source, kind))
+                    }),
+                ),
+                scheduled: vec![false; color.len()],
+                changed: Vec::new(),
+            }
+        });
+        Self {
+            color,
+            order,
+            boundary,
+            workspace,
+        }
+    }
+
+    pub fn resolve(&mut self, edge: &Graph, demand: &[Vec<usize>]) {
+        let mut color = Vec::new();
+        while self.workspace.is_some() {
+            let complete = demand.iter().all(|group| {
+                color.clear();
+                color.extend(group.iter().map(|&index| self.color[index]));
+                color.sort_unstable();
+                color.windows(2).all(|pair| pair[0] != pair[1])
+            });
+            if complete {
+                return;
+            }
+            self.step(edge);
+        }
+    }
+
+    pub fn color(&self) -> &[usize] {
+        &self.color
+    }
+
+    pub fn step(&mut self, edge: &Graph) -> bool {
+        let Some(workspace) = &mut self.workspace else {
+            return true;
+        };
+        workspace.changed.clear();
+        for start in workspace.pending.drain(..) {
+            workspace.scheduled[start] = false;
+            let end = self.boundary[start];
+            for &index in &self.order[start..end] {
+                let signature = &mut workspace.signature[workspace.range[index].clone()];
+                for (value, &(kind, target)) in signature.iter_mut().zip(&edge[index]) {
+                    *value = (kind, self.color[target]);
+                }
+                signature.sort_unstable();
+            }
+            self.order[start..end].sort_unstable_by(|&left, &right| {
+                workspace.signature[workspace.range[left].clone()]
+                    .cmp(&workspace.signature[workspace.range[right].clone()])
+            });
+            let mut partition = start;
+            for position in start + 1..end {
+                if workspace.signature[workspace.range[self.order[position - 1]].clone()]
+                    != workspace.signature[workspace.range[self.order[position]].clone()]
+                {
+                    self.boundary[partition] = position;
+                    partition = position;
+                }
+                if partition != start {
+                    workspace.changed.push((self.order[position], partition));
+                }
+            }
+            self.boundary[partition] = end;
+        }
+        if workspace.changed.is_empty() {
+            self.workspace = None;
+            return true;
+        }
+        for &(index, value) in &workspace.changed {
+            self.color[index] = value;
+        }
+        for &(index, _) in &workspace.changed {
+            for &(_, source) in &workspace.incoming[index] {
+                let start = self.color[source];
+                if self.boundary[start] - start > 1
+                    && !std::mem::replace(&mut workspace.scheduled[start], true)
+                {
+                    workspace.pending.push(start);
+                }
+            }
+        }
+        false
+    }
+
+    #[cfg(test)]
+    pub fn finish(mut self) -> Vec<usize> {
+        assert!(self.workspace.is_none());
+        let mut start = 0;
+        let mut ordinal = 0;
+        while start < self.order.len() {
+            let end = self.boundary[start];
+            for &index in &self.order[start..end] {
+                self.color[index] = ordinal;
+            }
+            ordinal += 1;
+            start = end;
+        }
+        self.color
+    }
